-- EVT hook file for team_dock_formation_menu (VRFW.host handlers, docs/internal/lua-hosts.md). Graft hero_style (betterqol_hero_style_dock.lua). Generated by research/scripts/menu_assemble.py; do not edit by hand.
-- Hero style selector, team dock part (team_dock_formation_menu): the popup row, the window and the style change.
BetterQoL = type(BetterQoL) == "table" and BetterQoL or {}
if BetterQoL.hero_style_dock == nil then
  local D = {
    ROW = 140,                        -- the added row id of the player popup (no retail setting type uses it)
    TEXT = 1130947576,                -- better_qol_hero_style
    CMD_PC_STATE = 1592681142,        -- CMND_BETTERQOL_PC_STATE (handle) -> param, build and passive slots as one line
    CMD_SET_CHARA_RARITY = 1641888398,
    CMD_IS_OPEN_MENU_OBJECT = 3693934564,
    CMD_WINDOW_POSITION = 63483614,   -- (x, y) of the sub-window
    SUB_WINDOW = 968210065,           -- sub_window
    CURSOR = 2296367164,              -- cmn05_01_cursor
    CMD_CLOSE_MENU_OBJECT = 320421347,
    RARITY_WINDOW = 27,               -- the game's avatar rarity window type
    WINDOW_SIZE = 5,                  -- its size code
    WINDOW_X = 500,                   -- its position (the game's avatar rarity window)
    WINDOW_Y = -318,
  }
  BetterQoL.hero_style_dock = D

  -- The player's passive state line (param, build, passive slots), "" when unknown.
  function D.state(handle)
    local ok, line = pcall(funcLuaCommand, D.CMD_PC_STATE, handle)
    return (ok and type(line) == "string") and line or ""
  end

  -- The window's pick: the chosen row is kept and the window closes.
  function BetterQoL_HeroStyleClose(position)
    if type(position) == "number" and position >= 0 then
      D.picked = position
    end
    funcLuaCommand(D.CMD_CLOSE_MENU_OBJECT, D.SUB_WINDOW)
  end

  -- The window's focus: nothing to preview (the banner is the row itself).
  function BetterQoL_HeroStyleFocus()
  end

  -- Runs in the popup's coroutine: the window, then the chosen style on the card.
  function D.run(context)
    local S = BetterQoL.HeroStyle
    local handle = context.handle
    local current = S ~= nil and S.style_of(handle) or nil
    if current == nil then
      return
    end
    local styles = S.styles()
    local enabled, checks = {}, {}
    for i = 1, #styles do
      enabled[i] = 1
      checks[i] = i == current and 1 or 0
    end
    D.picked = nil
    MENU_DEF.OpenSubWindow("BetterQoL_HeroStyleClose", "BetterQoL_HeroStyleFocus", #styles, {}, D.WINDOW_SIZE, 0,
      enabled, current - 1, false, false, D.RARITY_WINDOW, 0, {}, -1, {}, {}, handle, checks)
    waitTrue(function()
      return funcLuaCommand(D.CMD_IS_OPEN_MENU_OBJECT, D.SUB_WINDOW, D.CURSOR)
    end)
    funcLuaCommand(D.CMD_WINDOW_POSITION, D.WINDOW_X, D.WINDOW_Y)
    WaitCloseSubWindow()
    local picked = D.picked
    D.picked = nil
    local style = picked ~= nil and styles[picked + 1] or nil
    local before_rarity = S.rarity(handle)
    if style == nil or style == before_rarity then
      return
    end
    local before = D.state(handle)
    funcLuaCommand(D.CMD_SET_CHARA_RARITY, handle, style)
    local after = D.state(handle)
    S.log("style", before_rarity, "->", S.rarity(handle), "handle", handle,
      before ~= "" and before == after and "build, board and passives unchanged" or "STATE CHANGED",
      "before [" .. before .. "] after [" .. after .. "]")
    if type(RefreshCharaCardView) == "function" then
      RefreshCharaCardView(false)
    end
    if type(UpdateTeamCharaOrganizationErrorMassage) == "function" then
      UpdateTeamCharaOrganizationErrorMassage()
    end
  end

  if VRFW ~= nil and VRFW.list_rows ~= nil then
    VRFW.list_rows.add(VRFW.list_rows.PLAYER_COMMANDS, {id = "BetterQoL.hero_style", row = D.ROW, text = D.TEXT,
      when = function(context)
        return BetterQoL.HeroStyle ~= nil and BetterQoL.HeroStyle.style_of(context.handle) ~= nil
      end,
      run = D.run})
  end
end
